<?php
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);if(isset($_POST['delete'])){$q=$pdo->prepare('DELETE FROM products WHERE id=?');$q->execute([$id]);flash('Product deleted.');redirect('products.php');}}
$rows=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();admin_header('Products');$f=get_flash();if($f)echo '<div class="notice">'.e($f['message']).'</div>'; ?><p><a class="button" href="product-edit.php">ADD PRODUCT</a></p><div class="admin-panel table-wrap"><table><tr><th>Image</th><th>Name / SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $p):?><tr><td><img class="thumb" src="../<?=e(product_image($p['image']))?>" alt=""></td><td><?=e($p['name'])?><br><small><?=e($p['sku'])?></small></td><td><?=e($p['category_name']??'—')?></td><td><?=money((float)$p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['active']?'Active':'Hidden'?></td><td><a href="product-edit.php?id=<?=$p['id']?>">Edit</a> <form class="inline" method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="delete" value="1">Delete</button></form></td></tr><?php endforeach;?></table></div><?php admin_footer(); ?>
